-- Seeded local database only; all changes roll back.
begin;
create function pg_temp.check_ok(value boolean,message text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'FAILED: %',message;end if;end$$;
create function pg_temp.denied(statement text) returns void language plpgsql as $$begin begin execute statement;exception when others then return;end;raise exception 'FAILED: permitted %',statement;end$$;
create function pg_temp.upload(category text,phase int default null) returns uuid language plpgsql as $$
declare path text;d public.counselling_documents;result uuid;
begin
 path='10000000-0000-4000-8000-000000000001/30000000-0000-4000-8000-000000000001/counselling/'||gen_random_uuid()::text||'.pdf';
 insert into storage.objects(bucket_id,name,metadata) values('student-documents',path,'{"mimetype":"application/pdf","size":4194304}');
 select * into d from public.counselling_documents where student_id='30000000-0000-4000-8000-000000000001' and doc_category=category and phase_number is not distinct from phase;
 perform public.finalize_counselling_upload('30000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000001',category,phase,path,'fixture.pdf','Fixture '||category,d.id,d.created_at);
 select id into result from public.counselling_documents where student_id='30000000-0000-4000-8000-000000000001' and doc_category=category and phase_number is not distinct from phase;return result;
end$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000002',true);
select pg_temp.denied($q$select public.counselling_outcome('30000000-0000-4000-8000-000000000001',1,'not_allotted')$q$);
select public.save_counselling_states('30000000-0000-4000-8000-000000000001',array['Bihar','Delhi']);
select pg_temp.denied($q$select public.save_counselling_states('30000000-0000-4000-8000-000000000001',array['Bihar','Bihar'])$q$);
select pg_temp.denied($q$select public.save_counselling_states('30000000-0000-4000-8000-000000000001',array['Bihar','Delhi','Goa','Punjab','Kerala','Assam'])$q$);
select pg_temp.denied($q$select public.save_counselling_states('30000000-0000-4000-8000-000000000001',array['Mars'])$q$);
select pg_temp.denied($q$update public.student_counselling set current_phase=6$q$);
select pg_temp.denied($q$insert into public.counselling_documents(student_id,branch_id,doc_category,label,file_path,file_name) values('30000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','security_deposit','forged','fake.pdf','fake.pdf')$q$);
select pg_temp.denied($q$select public.finalize_counselling_upload('30000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000001','choice_pdf',1,'fake.pdf','fake.pdf','fake')$q$);
reset role;
select pg_temp.denied($q$select pg_temp.upload('choice_pdf',2)$q$);
select pg_temp.denied($q$select pg_temp.upload('stage_doc_4_5')$q$);
select pg_temp.denied($q$select pg_temp.upload('allotment_letter',1)$q$);
select pg_temp.denied($q$select pg_temp.upload('new_choice_pdf')$q$);
select pg_temp.upload('security_deposit');select pg_temp.upload('stage_doc_1_3');select pg_temp.upload('choice_pdf',1);
select pg_temp.check_ok((select bool_and(not show_to_student) from public.counselling_documents),'Every upload defaults hidden');
set local role service_role;
select public.student_login('CS-PAT-2026-0001','2007-05-12','counselling-test','counselling-token');
select pg_temp.check_ok(public.student_portal('30000000-0000-4000-8000-000000000001','counselling-token')->'counselling_documents'='[]'::jsonb,'Hidden documents absent from portal');
select pg_temp.denied($q$select public.counselling_document_access((select id from public.counselling_documents where doc_category='choice_pdf'),null,'30000000-0000-4000-8000-000000000001','counselling-token')$q$);
reset role;
set local role authenticated;
update public.counselling_documents set show_to_student=true where doc_category='choice_pdf';
select public.counselling_outcome('30000000-0000-4000-8000-000000000001',1,'not_allotted');
select pg_temp.denied($q$select public.counselling_outcome('30000000-0000-4000-8000-000000000001',1,'not_allotted')$q$);
select public.reuse_counselling_choice('30000000-0000-4000-8000-000000000001',2,(select id from public.counselling_documents where doc_category='choice_pdf' and phase_number=1));
select pg_temp.check_ok((select not show_to_student and reused_from_doc_id is not null from public.counselling_documents where doc_category='choice_pdf' and phase_number=2),'Reuse creates a separate hidden slot');
reset role;
select pg_temp.upload('choice_pdf',1);
select pg_temp.check_ok((select a.file_path<>b.file_path from public.counselling_documents a,public.counselling_documents b where a.doc_category='choice_pdf' and a.phase_number=1 and b.doc_category='choice_pdf' and b.phase_number=2),'Replacing original preserves reused snapshot');
select pg_temp.check_ok((select count(*)=1 from public.counselling_documents where doc_category='stage_doc_1_3'),'Stage group retains single inherited document');
set local role authenticated;
select public.counselling_outcome('30000000-0000-4000-8000-000000000001',2,'allotted');
select pg_temp.denied($q$select public.counselling_outcome('30000000-0000-4000-8000-000000000001',2,'not_allotted')$q$);
reset role;
select pg_temp.upload('allotment_letter',2);
select pg_temp.denied($q$select pg_temp.upload('new_allotment_letter')$q$);
select pg_temp.denied($q$select pg_temp.upload('upgraded_allotment_letter')$q$);
select pg_temp.upload('new_choice_pdf');select pg_temp.upload('new_allotment_letter');select pg_temp.upload('upgrade_choice_pdf');select pg_temp.upload('upgraded_allotment_letter');
set local role authenticated;
update public.counselling_documents set show_to_student=true where doc_category='allotment_letter';
select public.save_counselling_states('30000000-0000-4000-8000-000000000001',array['Goa']);
select pg_temp.check_ok((select preferred_states=array['Goa'] and allotted_phase=2 and finished from public.student_counselling),'States remain editable after allotment');
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000004',true);
select pg_temp.check_ok((select count(*)=0 from public.student_counselling),'Caller cannot read counselling state');
select pg_temp.check_ok((select count(*)=0 from public.counselling_documents),'Caller cannot read files');
select pg_temp.denied($q$select public.save_counselling_states('30000000-0000-4000-8000-000000000001','{}')$q$);
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000003',true);
select pg_temp.check_ok((select count(*)=0 from public.counselling_documents),'Other head cannot read counselling');
select pg_temp.denied($q$select public.save_counselling_states('30000000-0000-4000-8000-000000000001','{}')$q$);
reset role;
set local role service_role;
select pg_temp.check_ok((public.student_portal('30000000-0000-4000-8000-000000000001','counselling-token')->'counselling_documents') @> '[{"label":"Fixture allotment_letter","file_name":"fixture.pdf"}]'::jsonb,'Student sees shared letter');
select pg_temp.check_ok(not (public.student_portal('30000000-0000-4000-8000-000000000001','counselling-token') ? 'preferred_states'),'Student sees no internal counselling state');
select pg_temp.check_ok(not ((public.student_portal('30000000-0000-4000-8000-000000000001','counselling-token')->'counselling_documents'->0) ? 'file_path'),'No storage path in projection');
select public.counselling_document_access((select id from public.counselling_documents where doc_category='allotment_letter'),null,'30000000-0000-4000-8000-000000000001','counselling-token');
select pg_temp.denied($q$select public.counselling_document_access((select id from public.counselling_documents where doc_category='allotment_letter'),null,'30000000-0000-4000-8000-000000000003','counselling-token')$q$);
reset role;
update public.staff_profiles set is_active=false where id='20000000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000002',true);
select pg_temp.check_ok((select count(*)=0 from public.counselling_documents),'Inactive head loses files');
select pg_temp.denied($q$select public.save_counselling_states('30000000-0000-4000-8000-000000000001','{}')$q$);
reset role;
select pg_temp.denied($q$select public.counselling_document_access((select id from public.counselling_documents where doc_category='allotment_letter'),'20000000-0000-4000-8000-000000000002')$q$);
update public.staff_profiles set is_active=true where id='20000000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000001',true);
select pg_temp.check_ok((select count(*)=9 from public.counselling_documents),'Owner sees all slots');
reset role;
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000002',true);
do $$
declare path text;p int;target uuid='30000000-0000-4000-8000-000000000002';branch uuid='10000000-0000-4000-8000-000000000001';head uuid='20000000-0000-4000-8000-000000000002';
begin
 perform public.save_counselling_states(target,'{}');
 for p in 1..6 loop
  path=branch::text||'/'||target::text||'/counselling/'||gen_random_uuid()::text||'.pdf';
  insert into storage.objects(bucket_id,name,metadata) values('student-documents',path,'{"mimetype":"application/pdf","size":10}');
  perform public.finalize_counselling_upload(target,head,branch,'choice_pdf',p,path,'phase.pdf','Choice');
  if p in (4,6) then
   perform private.check_counselling_slot(target,case p when 4 then 'stage_doc_4_5' else 'stage_doc_6' end,null);
  end if;
  perform public.counselling_outcome(target,p,'not_allotted');
 end loop;
 perform pg_temp.check_ok((select current_phase=6 and finished and allotted_phase is null from public.student_counselling where student_id=target),'Phase 6 finishes without phase 7');
 perform pg_temp.denied($q$select public.counselling_outcome('30000000-0000-4000-8000-000000000002',6,'allotted')$q$);
end$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000001',true);
select public.transfer_student('30000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000002');
set constraints all immediate;
select pg_temp.check_ok((select bool_and(branch_id='10000000-0000-4000-8000-000000000002') from public.counselling_documents where student_id='30000000-0000-4000-8000-000000000001'),'Transfer moves all counselling slots');
select pg_temp.check_ok((select branch_id='10000000-0000-4000-8000-000000000002' from public.student_counselling where student_id='30000000-0000-4000-8000-000000000001'),'Transfer moves counselling state');
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000002',true);
select pg_temp.check_ok((select count(*)=0 from public.counselling_documents where student_id='30000000-0000-4000-8000-000000000001'),'Source head loses access on transfer');
reset role;
set local role service_role;
select public.counselling_document_access((select id from public.counselling_documents where doc_category='allotment_letter'),'20000000-0000-4000-8000-000000000003');
select pg_temp.denied($q$select public.counselling_document_access((select id from public.counselling_documents where doc_category='allotment_letter'),null,'30000000-0000-4000-8000-000000000001','counselling-token')$q$);
reset role;
select pg_temp.check_ok((select count(*)>=9 from public.audit_logs where entity_type='counselling_documents' and action='upload' and actor_id='20000000-0000-4000-8000-000000000002'),'Uploads audit the actual staff actor');
select pg_temp.check_ok((select count(*)>=2 from public.audit_logs where entity_type='student_counselling' and action='update'),'Phase changes audited');
rollback;
